import React, { useState, useRef, useEffect } from "react";
import { EmojiPickerWrapper } from "./EmojiPickerWrapper";
import AttachFileIcon from "@mui/icons-material/AttachFile";
import SendIcon from "@mui/icons-material/Send";
import SettingsVoiceIcon from "@mui/icons-material/SettingsVoice";

const MessageInput = ({ onSendMessage, onTyping, onStopTyping }) => {
  const [message, setMessage] = useState("");
  const [showPicker, setShowPicker] = useState(false);
  const [previewImage, setPreviewImage] = useState(null);
  const [attachedFile, setAttachedFile] = useState(null);
  const [audioBlob, setAudioBlob] = useState(null);
  const [isRecording, setIsRecording] = useState(false);

  const emojiPickerRef = useRef(null);
  const fileInputRef = useRef(null);
  const inputRef = useRef(null);
  const mediaRecorderRef = useRef(null);
  const isTypingRef = useRef(false);

  // ---------------- Emoji Picker ----------------
  const handleEmojiSelect = (emoji) => {
    setMessage((prev) => prev + emoji);
    setShowPicker(false);
  };

  useEffect(() => {
    const handleClickOutside = (event) => {
      if (emojiPickerRef.current && !emojiPickerRef.current.contains(event.target)) {
        setShowPicker(false);
      }
    };
    document.addEventListener("mousedown", handleClickOutside);
    return () => document.removeEventListener("mousedown", handleClickOutside);
  }, []);

  // ---------------- File Attach ----------------
  const handleFileAttach = (event) => {
    const file = event.target.files[0];
    if (!file) return;

    if (file.type.startsWith("image/") || file.type.startsWith("video/")) {
      const imageUrl = URL.createObjectURL(file);
      setPreviewImage(imageUrl);
      setAttachedFile(file);
      setAudioBlob(null); // clear audio if new file attached
    } else if (file.type.startsWith("audio/")) {
      setAttachedFile(file);
      setAudioBlob(file);
      setPreviewImage(null);
    } else {
      alert("Please select a valid image, video, or audio file.");
    }
    fileInputRef.current.value = null;
  };

  // ---------------- Audio Recording ----------------
  const handleStartRecording = async () => {
    if (!navigator.mediaDevices || !navigator.mediaDevices.getUserMedia) {
      alert("Audio recording not supported in this browser.");
      return;
    }

    try {
      const stream = await navigator.mediaDevices.getUserMedia({ audio: true });
      const mediaRecorder = new MediaRecorder(stream);
      mediaRecorderRef.current = mediaRecorder;
      const chunks = [];

      mediaRecorder.ondataavailable = (e) => chunks.push(e.data);
      mediaRecorder.onstop = () => {
        const blob = new Blob(chunks, { type: "audio/webm" });
        setAudioBlob(blob);
        setAttachedFile(blob);
        setPreviewImage(null); // clear image if recording
      };

      mediaRecorder.start();
      setIsRecording(true);
    } catch (err) {
      console.error("Microphone access error:", err);
      alert("Unable to access microphone.");
    }
  };

  const handleStopRecording = () => {
    if (mediaRecorderRef.current) {
      mediaRecorderRef.current.stop();
      setIsRecording(false);
    }
  };

  // ---------------- Send Message ----------------
  const handleSend = () => {
    if (!message.trim() && !attachedFile && !audioBlob) {
      alert("Please enter a message or attach a file.");
      return;
    }

    const formData = new FormData();
    if (message.trim()) formData.append("text", message);

    if (attachedFile) {
      // If it's an audio blob, give it a filename and type
      if (attachedFile instanceof Blob && attachedFile.type.startsWith("audio/")) {
        const file = new File([attachedFile], `recording_${Date.now()}.webm`, {
          type: attachedFile.type || "audio/webm",
        });
        formData.append("attachment", file);
      } else {
        formData.append("attachment", attachedFile);
      }
    }

    onSendMessage(message, attachedFile, previewImage);
    if (isTypingRef.current) {
      onStopTyping?.();
      isTypingRef.current = false;
    }
    setMessage("");
    setPreviewImage(null);
    setAttachedFile(null);
    setAudioBlob(null);
  };

  const handleInputChange = (e) => {
    const value = e.target.value;
    setMessage(value);

    if (!value.trim()) {
      if (isTypingRef.current) {
        onStopTyping?.();
        isTypingRef.current = false;
      }
      return;
    }

    if (!isTypingRef.current) {
      onTyping?.();
      isTypingRef.current = true;
    }
  };

  useEffect(() => {
    return () => {
      if (isTypingRef.current) {
        onStopTyping?.();
        isTypingRef.current = false;
      }
    };
  }, [onStopTyping]);


  const handleKeyDown = (event) => {
    if (event.key === "Enter" && !event.shiftKey) {
      event.preventDefault();
      handleSend();
    }
  };

  return (
    <div className="p-4 border-t bg-white flex items-center relative">
      {/* Emoji Picker Button */}
      <button onClick={() => setShowPicker((prev) => !prev)} className="mr-2">
        😊
      </button>

      {showPicker && (
        <div ref={emojiPickerRef} className="absolute bottom-16 left-0 z-50">
          <EmojiPickerWrapper onEmojiSelect={handleEmojiSelect} />
        </div>
      )}

      {/* Message Input */}
      <div className="relative flex w-1/2 items-center">
        <div className="flex items-center w-full p-2 border border-gray-300 rounded-lg">
          {previewImage && (
            <div className="flex items-center space-x-2">
              <img
                src={previewImage}
                alt="Preview"
                className="h-10 w-10 object-cover rounded"
              />
              <button
                onClick={() => {
                  URL.revokeObjectURL(previewImage);
                  setPreviewImage(null);
                  setAttachedFile(null);
                }}
                className="text-red-500 text-sm"
              >
                ✕
              </button>
            </div>
          )}

          {audioBlob && (
            <div className="flex items-center space-x-2">
              <audio controls src={URL.createObjectURL(audioBlob)} className="h-10" />
              <button
                onClick={() => {
                  setAudioBlob(null);
                  setAttachedFile(null);
                }}
                className="text-red-500 text-sm"
              >
                ✕
              </button>
            </div>
          )}

          <input
            type="text"
            ref={inputRef}
            value={message}
            onChange={handleInputChange}
            onKeyDown={handleKeyDown}
            placeholder="Type your message..."
            className="w-full outline-none"
          />
        </div>

        {/* File Attach */}
        <AttachFileIcon
          className="absolute right-14 text-gray-500 cursor-pointer"
          onClick={() => fileInputRef.current.click()}
        />
        <input
          type="file"
          ref={fileInputRef}
          style={{ display: "none" }}
          onChange={handleFileAttach}
        />

        {/* Voice Recording */}
        <SettingsVoiceIcon
          className={`absolute right-2 cursor-pointer ${isRecording ? "text-red-500" : "text-gray-500"}`}
          onClick={isRecording ? handleStopRecording : handleStartRecording}
        />
      </div>

      {/* Send Button */}
      <button type="button" className="ml-3 text-blue-500" onClick={handleSend}>
        <SendIcon />
      </button>
    </div>
  );
};

export default MessageInput;
